{
  "title": "赛博长安",
  "scene": "在这个赛博朋克风的长安城里，古老的建筑与高科技设施并存。街道上的人们穿着现代与传统结合的服装，机器猫懒散地坐在街边的机器人餐馆里。空气中弥漫着一股混合着科技与烟火气的味道。今天是期末考试的日子，但在这个充满机遇的地方，考试似乎被赋予了新的意义。",
  "goal": "玩家需要找到一把会说话的剑，作为期末考试的特殊考试题目，以证明自己的见识与智慧。",
  "choices": [
    {
      "id": "A",
      "text": "向机器猫打听会说话的剑的下落。",
      "outcome": "机器猫懒洋洋地说：‘哦，那把剑啊，它现在在城北的废墟里，那里不时会有危险出现。’",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "去城北的废墟寻找剑",
      "outcome": "玩家小心翼翼地穿过废墟，不时被废墟中的陷阱所干扰。终于在一处隐蔽的地方找到了会说话的剑，剑上刻着一些奇怪的文字。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "询问路边的行人关于会说话的剑的事",
      "outcome": "人们耸耸肩，似乎并不知道剑的具体位置，但有人提到剑可能与废墟里的某个故事有关。"
      "result": "partial",
      "next": "retry"
    }
  ]
}
